<script lang="ts">import {goto} from '$app/navigation';import {auth} from '$lib/api';import {session} from '$lib/stores/session'; let role=$state<'farmer'|'producer'>('farmer'); let name=$state(''); let email=$state(''); let password=$state(''); let error=$state(''); let loading=$state(false); async function submit(){if(!name||!email||!password){error='Complete all fields.';return} loading=true;error='';try{const result=await auth.register({name,email,password,role});session.set(result.user);goto('/dashboard')}catch(e){error=e instanceof Error?e.message:'Unable to create account.'}finally{loading=false}}</script><main class="auth wrap"><p class="eyebrow">JOIN THE MARKETPLACE</p><h1>Start your<br/><em>next season.</em></h1><div class="toggle"><button class:active={role==='farmer'} onclick={()=>role='farmer'}>I'm a Farmer</button><button class:active={role==='producer'} onclick={()=>role='producer'}>I'm a Producer</button></div><form onsubmit={(e)=>{e.preventDefault();submit()}}><label>{role==='farmer'?'Farm':'Business'} name<input bind:value={name} required /></label>{#if error}<p class="error">{error}</p>{/if}<label>Email<input bind:value={email} type="email" required /></label><label>Password<input bind:value={password} type="password" required /></label><button class="btn primary" disabled={loading}>{loading?'Creating account…':'Create account ↗'}</button></form></main>
